require_relative "shellwords_mojo_native"

module Shellwords
  def self.shellsplit(line)
    MojoAnythingNativeShellwordsMojo.call("shellsplit", line)
  end

  def self.shellescape(str)
    MojoAnythingNativeShellwordsMojo.call("shellescape", str)
  end

  def self.shelljoin(array)
